def _format_float(value):
    """Format a floating number to make sure it gets the decimal point."""
    # First try Python's default string representation, which is usually
    # the shortest representation that preserves the value exactly.
    value_str = str(value)

    # Normalize lowercase 'e' to uppercase 'E' for FITS compatibility.
    if "e" in value_str:
        value_str = value_str.replace("e", "E")

    # Check if the string is suitable for FITS:
    # 1. Must fit in 20 characters
    # 2. Must have a decimal point or E notation (to distinguish from integer)
    if len(value_str) <= 20 and ("." in value_str or "E" in value_str):
        # Handle E notation normalization (pad exponent to 2 digits)
        if "E" in value_str:
            significand, exponent = value_str.split("E")
            if exponent[0] in ("+", "-"):
                sign = exponent[0]
                exponent = exponent[1:]
            else:
                sign = ""
            value_str = f"{significand}E{sign}{int(exponent):02d}"
        return value_str

    # Fall back to the original formatting approach.
    value_str = f"{value:.16G}"
    if "." not in value_str and "E" not in value_str:
        value_str += ".0"
    elif "E" in value_str:
        # On some Windows builds of Python (and possibly other platforms?) the
        # exponent is zero-padded out to, it seems, three digits.  Normalize
        # the format to pad only to two digits.
        significand, exponent = value_str.split("E")
        if exponent[0] in ("+", "-"):
            sign = exponent[0]
            exponent = exponent[1:]
        else:
            sign = ""
        value_str = f"{significand}E{sign}{int(exponent):02d}"

    # Limit the value string to at most 20 characters.
    str_len = len(value_str)

    if str_len > 20:
        idx = value_str.find("E")

        if idx < 0:
            value_str = value_str[:20]
        else:
            value_str = value_str[: 20 - (str_len - idx)] + value_str[idx:]

    return value_str


